@Service
public class ZadaniaService {

    @Cacheable(value = "zadania", key = "#id")
    public Zadanie znajdzZadanie(Long id) {
        return repository.findById(id).orElseThrow();
    }

    @CachePut(value = "zadania", key = "#zadanie.id")
    public Zadanie zaktualizujZadanie(Zadanie zadanie) {
        return repository.save(zadanie);   // ZAWSZE zapisuje do bazy I aktualizuje cache
    }

    @CacheEvict(value = "zadania", key = "#id")
    public void usunZadanie(Long id) {
        repository.deleteById(id);          // USUWA wpis z cache PO usunieciu z bazy
    }
}

@Cacheable(value = "zadania", key = "#zadanie.id")
public Zadanie zaktualizujZadanie(Zadanie zadanie) {
